from pathlib import Path

path = Path('TimeRange.js')
text = path.read_text()

old = '''    static #calculateTimeAngle(\n        time,\n        origin\n    ) {\n        const millisecondsInHour =\n            60 *\n            60 *\n            1000;\n\n        let milliseconds;\n\n        if (\n            origin instanceof Date\n        ) {\n            const difference =\n                time.getTime() -\n                origin.getTime();\n\n            if (\n                difference >= 0 &&\n                difference <=\n                    millisecondsInHour\n            ) {\n                milliseconds =\n                    difference;\n            }\n            else {\n                milliseconds =\n                    (\n                        difference %\n                            millisecondsInHour +\n                        millisecondsInHour\n                    ) %\n                    millisecondsInHour;\n            }\n        }\n        else {\n            milliseconds =\n                time.getMinutes() *\n                    60 *\n                    1000 +\n                time.getSeconds() *\n                    1000 +\n                time.getMilliseconds();\n        }\n\n        return (\n            360 /\n            millisecondsInHour\n        ) *\n        milliseconds;\n    }\n'''

new = '''    static #getGroupTimeBounds(\n        parent\n    ) {\n        if (\n            !parent ||\n            typeof parent.querySelectorAll !==\n                "function"\n        ) {\n            return;\n        }\n\n        let earliestStart;\n        let latestEnd;\n\n        for (\n            const range of\n                parent.querySelectorAll(\n                    "time-range"\n                )\n        ) {\n            if (\n                !(range instanceof TimeRange) ||\n                range.#pendingRemoval ||\n                !(range.#startTime instanceof Date) ||\n                !(range.#endTime instanceof Date)\n            ) {\n                continue;\n            }\n\n            const start =\n                range.#startTime.getTime();\n\n            const end =\n                range.#endTime.getTime();\n\n            if (\n                earliestStart === undefined ||\n                start < earliestStart\n            ) {\n                earliestStart = start;\n            }\n\n            if (\n                latestEnd === undefined ||\n                end > latestEnd\n            ) {\n                latestEnd = end;\n            }\n        }\n\n        if (\n            earliestStart === undefined ||\n            latestEnd === undefined ||\n            latestEnd <= earliestStart\n        ) {\n            return;\n        }\n\n        return {\n            start: earliestStart,\n            end: latestEnd\n        };\n    }\n\n    static calculateTimeAngle(\n        time,\n        origin,\n        parent = undefined\n    ) {\n        if (!(time instanceof Date)) {\n            return;\n        }\n\n        if (parent !== undefined) {\n            const bounds =\n                TimeRange.#getGroupTimeBounds(\n                    parent\n                );\n\n            if (!bounds) {\n                return;\n            }\n\n            return (\n                (\n                    time.getTime() -\n                    bounds.start\n                ) /\n                (\n                    bounds.end -\n                    bounds.start\n                )\n            ) *\n            360;\n        }\n\n        const millisecondsInHour =\n            60 *\n            60 *\n            1000;\n\n        let milliseconds;\n\n        if (\n            origin instanceof Date\n        ) {\n            const difference =\n                time.getTime() -\n                origin.getTime();\n\n            if (\n                difference >= 0 &&\n                difference <=\n                    millisecondsInHour\n            ) {\n                milliseconds =\n                    difference;\n            }\n            else {\n                milliseconds =\n                    (\n                        difference %\n                            millisecondsInHour +\n                        millisecondsInHour\n                    ) %\n                    millisecondsInHour;\n            }\n        }\n        else {\n            milliseconds =\n                time.getMinutes() *\n                    60 *\n                    1000 +\n                time.getSeconds() *\n                    1000 +\n                time.getMilliseconds();\n        }\n\n        return (\n            360 /\n            millisecondsInHour\n        ) *\n        milliseconds;\n    }\n'''

if old not in text:
    raise SystemExit('calculateTimeAngle block not found')
text = text.replace(old, new, 1)

text = text.replace('''    #getEdgePoint(\n        angle,\n        width,\n        height\n    ) {''', '''    static calculateEdgePoint(\n        angle,\n        width,\n        height\n    ) {''', 1)

old_corners_sig = '''    #getCornersBetweenAngles(\n        startAngle,\n        endAngle,\n        width,\n        height\n    ) {'''
new_corners_sig = '''    static calculateCorners(\n        startAngle,\n        endAngle,\n        width,\n        height,\n        parent = undefined,\n        mode = "radial"\n    ) {\n        const supportedModes =\n            new Set([\n                "radial",\n                "to-right",\n                "to-left",\n                "to-bottom",\n                "to-top"\n            ]);\n\n        if (!supportedModes.has(mode)) {\n            return;\n        }\n\n        if (\n            mode !== "radial" &&\n            parent === undefined\n        ) {\n            return;\n        }\n\n        if (mode !== "radial") {\n            const startProgress =\n                Math.max(\n                    0,\n                    Math.min(\n                        1,\n                        startAngle / 360\n                    )\n                );\n\n            const endProgress =\n                Math.max(\n                    0,\n                    Math.min(\n                        1,\n                        endAngle / 360\n                    )\n                );\n\n            if (mode === "to-right") {\n                const startX =\n                    width * startProgress;\n\n                const endX =\n                    width * endProgress;\n\n                return [\n                    { x: startX, y: 0 },\n                    { x: endX, y: 0 },\n                    { x: endX, y: height },\n                    { x: startX, y: height }\n                ];\n            }\n\n            if (mode === "to-left") {\n                const startX =\n                    width *\n                    (1 - startProgress);\n\n                const endX =\n                    width *\n                    (1 - endProgress);\n\n                return [\n                    { x: startX, y: 0 },\n                    { x: endX, y: 0 },\n                    { x: endX, y: height },\n                    { x: startX, y: height }\n                ];\n            }\n\n            if (mode === "to-bottom") {\n                const startY =\n                    height * startProgress;\n\n                const endY =\n                    height * endProgress;\n\n                return [\n                    { x: 0, y: startY },\n                    { x: width, y: startY },\n                    { x: width, y: endY },\n                    { x: 0, y: endY }\n                ];\n            }\n\n            const startY =\n                height *\n                (1 - startProgress);\n\n            const endY =\n                height *\n                (1 - endProgress);\n\n            return [\n                { x: 0, y: startY },\n                { x: width, y: startY },\n                { x: width, y: endY },\n                { x: 0, y: endY }\n            ];\n        }'''

if old_corners_sig not in text:
    raise SystemExit('corners signature not found')
text = text.replace(old_corners_sig, new_corners_sig, 1)

text = text.replace('TimeRange.#calculateTimeAngle(', 'TimeRange.calculateTimeAngle(')
text = text.replace('this.#getEdgePoint(', 'TimeRange.calculateEdgePoint(')
text = text.replace('this.#getCornersBetweenAngles(', 'TimeRange.calculateCorners(')

path.write_text(text)
